static int inc(int t)
{
    int minutes = t % 100;
    int hours = t / 100;
    minutes++;
    if (minutes == 60)
    {
        minutes = 0;
        hours++;
        if (hours == 24)
            hours = 0;
    }
    return minutes + hours * 100;
}
static int dec(int t)
{
    int minutes = t % 100;
    int hours = t / 100;
    minutes--;
    if (minutes == -1)
    {
        minutes = 59;
        hours--;
        if (hours == -1)
            hours = 23;
    }
    return minutes + hours * 100;
}
